#!/usr/bin/env python3
"""
Heroes.exe patch v8: Multi Game button + local lobby panel + Battaloon/Bone Dragon job change.

Usage:  python patch_heroes_multi_button.py Heroes.exe Heroes_patched.exe
Your original file is never modified. Requires the Steam build of
Aug 7 2020 (the script verifies the bytes it patches and refuses otherwise).

What it does:
  1. Title-menu constructor (0x7283d6): also creates control 0x24 and stores
     it at this+0x384 (object grown from 0x384 to 0x388 bytes).
  2. Title scene state 3 (main list, 0x6a73b9): confirming control 0x24 now
     enters state 5 (multiplayer sub-panel), exactly as Single Game enters state 4.
  3. Title-scene state 5 (multiplayer sub-panel, 0x6a76a0): adds the missing
     Back handling, makes "Sign Out" go back, and shows a placeholder message
     for the two Live entries.
  4. Title menu handler (0x728a13): ignores clicks on the three sub-panel entries,
     whose old Live-only effects crash the PC build.
  5. Stage-1 network experiment: builds the (stubbed) NetworkCmdManager when the battle
     owner is created in network mode, and holding F8 as a battle is set up forces
     network mode.
  6. Clears the DYNAMIC_BASE (ASLR) flag so absolute addresses used by the
     new code are valid (the game then loads at its preferred base 0x400000).
Code lives in unused int3 padding inside .text. All code is position
independent, so ASLR (DYNAMIC_BASE) is not a problem.
"""
import struct, os, sys

BASE_VA, TEXT_VA, TEXT_RAW = 0x401000, 0x401000, 0x400
def off(va):
    if 0xA42000 <= va < 0xA42000 + 0x1F600: return va - 0xA42000 + 0x640C00     # .data (initialised part)
    if 0x988000 <= va < 0x988000 + 0xB9A00: return va - 0x988000 + 0x587200     # .rdata
    return va - TEXT_VA + TEXT_RAW
def rel(src_end, dst): return struct.pack('<i', dst - src_end)

def call(at, dst): return b'\xe8' + rel(at + 5, dst)
def jmp(at, dst):  return b'\xe9' + rel(at + 5, dst)

CAVE_A, CAVE_B, CAVE_C = 0x4010E1, 0x8097DD, 0x81D7C8
CTOR_HOOK, SEL_HOOK = 0x7283D6, 0x7289BB
CREATE_CTRL, SET_FLAG, IS_CLICKED, SHOW_MULTI_PANEL = 0x6E23B0, 0x6E8FF0, 0x43B990, 0x728860
NEWSZ_ALLOC, NEWSZ_FREE = 0x6F0075, 0x7297D7
EXIT_SEL = 0x728BB6
SLACK_D, STATE5_HOOK, STATE5_EXIT, STATE5_CONT = 0x987C20, 0x6A76A0, 0x6A7702, 0x6A76A7
MSGBOX_THUNK = 0x8BA86C
KUF_VA = 0xAE1000
KJB_VA = 0xB13000   # v93 section .kjb: custom job icon blocks (0xB13000) + net module bss (0xB18000)
