def build():
    p = []  # (va, expected_old_bytes, new_bytes)

    # ---- title ctor: jump into the new .kuf section (creates control 0x24 + the lobby panel) ----
    p.append((CTOR_HOOK, b'\x8b\x95\xa4\xfe\xff\xff', jmp(CTOR_HOOK, KUF_VA) + b'\x90'))

    # ---- job change: allow Battaloon / Bone Dragon (skip the 'Change not allowed' check at 0x7046C0) ----
    p.append((0x7046C0, b'\x83\xbd\x9c\xfe\xff\xff', b'\xe9\x60\x00\x00\x00\x90'))

    # ---- stop the old title handler reacting to the three multiplayer sub-panel entries ----
    # (their old click codes lead to Live-only menus / a campaign start that crash here)
    p.append((0x728A13, b'\x8b\x45\xfc\x8b\x88', jmp(0x728A13, 0x728AC4)))

    # ---- slack cave E: title state 3 (main list) -> state 5 when Multi Game confirmed ----
    p.extend(build_state3_hook())

    # ---- slack cave D: multiplayer sub-panel (title state 5) handling ----
    p.append((STATE5_HOOK, b'\xc7\x45\xf0\x00\x00\x00\x00', jmp(STATE5_HOOK, KUF_VA + 0x400) + b'\x90\x90'))

    # ---- Start button: post Custom Campaign message (0x69) from the title menu update; Live maps in custom list ----
    p.append((0x728BB6, b'\x8b\x55\xfc\x83\xba\x90\x02\x00\x00\xff', jmp(0x728BB6, KUF_VA + 0xE20) + b'\x90' * 5))
    for va in (0x723094, 0x7230DA, 0x723957, 0x69B58E, 0x55334F):
        p.append((va, call(va, 0x6A8440), call(va, KUF_VA + 0xE00)))

    # ---- Live maps outside network mode: only slot 0 is the local human, other human slots become AI ----
    p.append((0x6A112C, b'\x8b\x4d\x08\x51\x8b\x0d\x34\x23\xa6\x00', jmp(0x6A112C, KUF_VA + 0xF00) + b'\x90' * 5))

    # ---- Live maps: after the custom army fill (slot 0 only), copy that army to the other human slots ----
    p.append((0x69B650, b'\xb9\x98\x51\xa7\x00', jmp(0x69B650, KUF_VA + 0xF40)))

    # ---- Live maps: skip Custom Battle's enemy fill (it claims slot 1 for the Enemy Settings) ----
    p.append((0x69B693, call(0x69B693, 0x6B40A0), call(0x69B693, KUF_VA + 0x10EE)))

    # ---- Live maps: snapshot placement flags before the custom army fill (restored for AI slots) ----
    p.append((0x69B64B, call(0x69B64B, 0x6B2680), call(0x69B64B, KUF_VA + 0x110E)))

    # ---- Live maps: skip Custom Battle's per-type AI profile assignment (uses AI_Custom ids) ----
